import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let n = {n}, and consider any sequence of strictly increasing positive integers a_1 < a_2 < ... < a_{n}, each term a_i being a multiple of {step}, with total sum a_1 + a_2 + ... + a_{n} = {total_sum}. For any choice of {parts}-1 indices 1 <= k_1 < k_2 < ... < k_{parts_minus_one} <= n-1, form {parts} contiguous blocks: B_1 = (a_1, ..., a_{k_1}), B_2 = (a_{k_1+1}, ..., a_{k_2}), ..., B_{parts} = (a_{k_{parts_minus_one}+1}, ..., a_n). Let S be the maximum, over all such partitions, of the minimum among the {parts} block sums. Among all such sequences, determine the minimal possible value of S.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Generate parameters for the harder generalization
# We choose n moderately large, parts between 2 and 8 (and <= n-1), and a step between 1 and 7.
# total_sum must be divisible by step and >= step * n(n+1)/2 to admit a strictly increasing sequence of multiples of step.
for _ in range(1000):
    n = rng.randint(24, 60)  # larger than seed length for added complexity
    parts = rng.randint(2, min(8, n - 1))
    # Bias towards parts >= 3 to make it more challenging
    if rng.random() < 0.6:
        parts = rng.randint(3, min(8, n - 1))
    step = rng.randint(1, 7)
    # Minimal feasible base sum (in units of step)
    base_min = n * (n + 1) // 2
    # Choose a base total >= base_min with some random slack to avoid trivial small answers
    slack = rng.randint(n, 5 * n)  # ensure variety and non-triviality
    base_total = base_min + slack
    total_sum = step * base_total
    # Compute the answer to ensure it's non-trivial and well-formed
    # Minimal S should be step * ceil(base_total / (parts + 1))
    # Ensure parts + 1 isn't too large compared to base_total (to avoid S = step)
    if parts + 1 <= base_total // 2:
        # All constraints satisfied
        return {
            'n': n,
            'total_sum': total_sum,
            'parts': parts,
            'parts_minus_one': parts - 1,
            'step': step
        }
# Fallback if retries failed
# Choose a deterministic safe instance
n = 40
parts = 4
step = 3
base_min = n * (n + 1) // 2
base_total = base_min + 3 * n
total_sum = step * base_total
return {
    'n': n,
    'total_sum': total_sum,
    'parts': parts,
    'parts_minus_one': parts - 1,
    'step': step
}

    def verifier(assign):
# Validate and compute the correct minimal S.
# Domain constraints:
# - n >= 2
# - parts in [2, n-1]
# - step >= 1
# - total_sum divisible by step
# - total_sum >= step * n(n+1)/2 (existence of strictly increasing multiples of step)
try:
    n = int(assign['n'])
    total_sum = int(assign['total_sum'])
    parts = int(assign['parts'])
    step = int(assign['step'])
    parts_minus_one = int(assign['parts_minus_one'])
except Exception:
    # Missing or bad types
    return (False, None)

# Basic checks
if n < 2:
    # Not enough elements to split
    return (False, None)
if parts < 2 or parts > n - 1:
    # Invalid partition count
    return (False, None)
if parts_minus_one != parts - 1:
    # Inconsistent helper
    return (False, None)
if step < 1:
    return (False, None)
if total_sum % step != 0:
    # Sum must be divisible by step because all a_i are multiples of step
    return (False, None)

# Feasibility of a strictly increasing sequence of multiples of step
min_sum = step * (n * (n + 1) // 2)
if total_sum < min_sum:
    # Impossible to realize such a sequence
    return (False, None)

# Compute the minimal possible S for this instance.
# Scaling argument: write a_i = step * x_i with x_i strictly increasing positive integers and sum sum_x = total_sum/step.
# For step=1, the generalized two-sided balancing result extends to p-way contiguous partitions:
# minimal achievable max over partitions of (min block sum) equals ceil(sum_x / (parts + 1)).
# Scaling back yields answer = step * ceil((total_sum/step) / (parts + 1)).
sum_x = total_sum // step
# Ceil division: ceil(sum_x / (parts + 1)) = (sum_x + parts) // (parts + 1)
import math
minimal_S = step * ((sum_x + parts) // (parts + 1))

# Additional difficulty guard: ensure the instance isn't trivially tiny
if minimal_S <= step:
    # S too small; instance likely trivial; reject
    return (False, None)

return (True, minimal_S)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

